import { ChevronRight } from 'lucide-react'
import type { ReactNode } from 'react'
import { cn } from '@/lib/cn'

// A row: media, a title in DM Sans Medium with a muted line under it, and what goes at the end. `variant` default has
// no fill (rows in a list, split by ItemGroup's hairlines), outline a #262626 hairline box, muted the card's #171717
// fill; both boxes take the brand corner. `size` sm is tighter. With `href` the whole row is one link that takes the
// ghost fill under the pointer (150ms), and `arrow` adds a chevron that brightens with it and never moves. A link holds
// no buttons: `actions` only show on a row without `href`.
export type ItemVariant = 'default' | 'outline' | 'muted'
export type ItemSize = 'default' | 'sm'

const VARIANTS: Record<ItemVariant, string> = {
  default: 'bg-transparent',
  outline: 'rounded-container border border-edge',
  muted: 'rounded-container bg-surface-raised',
}
const SIZES: Record<ItemSize, string> = { default: 'gap-4 p-4', sm: 'gap-3 px-4 py-3' }

export interface ItemProps {
  /** The title. */
  title?: string
  /** A muted line under the title (two lines at most). */
  description?: string
  /** default (no fill), outline (a hairline box) or muted (the card's fill). */
  variant?: ItemVariant
  /** default or sm (tighter). */
  size?: ItemSize
  /** The whole row opens this. */
  href?: string
  /** A chevron at the end of a link row. */
  arrow?: boolean
  /** Before the title: an icon, a logo, a thumbnail. */
  media?: ReactNode
  /** At the end, on a row without href: buttons, a tag, a time. */
  actions?: ReactNode
  className?: string
  /** The title, in place of `title`. */
  children?: ReactNode
}

export function Item({ title, description, variant = 'default', size = 'default', href, arrow, media, actions, className, children }: ItemProps) {
  const classes = cn('group/item flex min-w-0 items-center', VARIANTS[variant] ?? VARIANTS.default, SIZES[size] ?? SIZES.default)
  const body = (
    <>
      {media && <span className="flex shrink-0 items-center justify-center text-fg-soft">{media}</span>}
      <span className="flex min-w-0 flex-1 flex-col gap-1">
        <span className="truncate type-ui-strong text-fg">{children ?? title}</span>
        {description && <span className="line-clamp-2 type-ui text-fg-muted">{description}</span>}
      </span>
    </>
  )
  if (href) {
    return (
      <a data-ds="item" href={href} className={cn(classes, 'cursor-pointer rounded-container transition-[background-color] duration-150 ease-standard hover:bg-action-ghost-hover', className)}>
        {body}
        {arrow && <ChevronRight size={16} strokeWidth={1.5} className="shrink-0 text-fg-muted transition-[color] duration-150 ease-standard group-hover/item:text-fg" aria-hidden="true" />}
      </a>
    )
  }
  return (
    <div data-ds="item" className={cn(classes, className)}>
      {body}
      {actions && <span className="flex shrink-0 items-center gap-2">{actions}</span>}
    </div>
  )
}

export default Item

import type { HTMLAttributes } from 'react'
import { cn } from '@/lib/cn'

// Rows of one list, a #262626 hairline between each. Put Item rows in it, one per <li>.
export type ItemGroupProps = HTMLAttributes<HTMLUListElement>

export function ItemGroup({ className, children, ...rest }: ItemGroupProps) {
  return <ul data-ds="item-group" className={cn('flex flex-col [&>*+*]:border-t [&>*+*]:border-edge', className)} {...rest}>{children}</ul>
}

export default ItemGroup

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}
